from ..section_generic import TextBasedSectionGeneric


class SectionIpConfiguration(TextBasedSectionGeneric):
    """
    Section "ip_configuration" is a part of cus.ini config file.
    Generated content base on epc.yaml.
    Example generated for CLOUD_R4A_CUS:

    [ip_configuration]
    workstation_ip_addr = 192.168.200.126
    netmask             = 255.255.255.0
    lte_network_gw      = 10.0.2.1
    ss_ip_addr_pool     = 185.4.0.0/16
    """
    def __init__(self, subsection_separator='\n'):
        super().__init__(subsection_separator)
        self._section_header = '[ip_configuration]'

    def _prepare_section_content(self, epc_config, *args, **kwargs):

        workstation_ip_addr = epc_config['uesim_ip_configuration']['workstation_ip_addr']
        netmask = epc_config['uesim_ip_configuration']['netmask']
        lte_network_gw = epc_config['uesim_ip_configuration']['lte_network_gw']
        ss_ip_addr_pool = epc_config['uesim_ip_configuration']['ss_ip_addr_pool']
        # ue_ip_addr_pool = (epc_config['uesim_ip_configuration']['ue_ip_addr_pool']
        #                    if 'ue_ip_addr_pool' in epc_config['uesim_ip_configuration']
        #                    else None)

        self._section_content = [[
            self._section_header,
            f'workstation_ip_addr = {workstation_ip_addr}',
            f'netmask             = {netmask}',
            f'lte_network_gw      = {lte_network_gw}',
            f'ss_ip_addr_pool     = {ss_ip_addr_pool}'
        ]]

        # if ue_ip_addr_pool:
        #     self._section_content[0].append(f'ue_ip_addr_pool     = {ue_ip_addr_pool}')
